INSERT INTO reviews (id, user_id, product_id, rating, body, status, is_featured, moderated_by, moderated_at, created_at) VALUES
(1, 3, 6, 5, 'Плед невероятно тёплый и мягкий, цвет точно как на фото. Уже второй месяц не расстаёмся с ним по вечерам.', 'approved', 1, 2, '2026-07-10 10:00:00', '2026-07-09 20:15:00'),
(2, 4, 11, 5, 'Лампа даёт очень уютный тёплый свет, идеально для вечернего чтения. Собрана аккуратно, ничего не болтается.', 'approved', 1, 2, '2026-07-11 09:30:00', '2026-07-10 21:00:00'),
(3, 5, 21, 4, 'Приятный ненавязчивый аромат сандала, горит долго и равномерно. Возьму ещё в подарок подруге.', 'approved', 1, 2, '2026-07-12 11:00:00', '2026-07-11 19:45:00'),
(4, 6, 2, 5, 'Кашпо отлично смотрится с крупным фикусом, лоза плотная и аккуратно сплетена.', 'approved', 0, 2, '2026-06-15 10:00:00', '2026-06-14 16:20:00'),
(5, 7, 17, 4, 'Зеркало лёгкое, но рама выглядит основательно. Повесили в прихожей — стало заметно светлее.', 'approved', 0, 1, '2026-06-20 12:00:00', '2026-06-19 14:10:00'),
(6, 3, 8, 5, 'Скатерть из плотного льна, после стирки не села. Смотрится очень достойно на праздничном столе.', 'approved', 0, 2, '2026-07-09 08:00:00', '2026-07-08 12:30:00'),
(7, 8, 14, 4, 'Бра мягко подсвечивает стену, форма полумесяца — как отдельный элемент декора даже при выключенном свете.', 'approved', 0, 2, '2026-07-15 09:00:00', '2026-07-14 20:05:00'),
(8, 4, 23, 5, 'Диффузор наполняет комнату лёгким ванильным ароматом без резкости. Хватает надолго.', 'approved', 0, 2, '2026-07-16 10:15:00', '2026-07-15 18:40:00'),
(9, 5, 9, 3, 'Плед тёплый, но расцветка немного темнее, чем на фото на сайте.', 'pending', 0, NULL, NULL, '2026-07-25 13:00:00'),
(10, 6, 16, 4, 'Панно macrame хорошо дополнило гостиную, но крепление в комплекте слабоватое.', 'pending', 0, NULL, NULL, '2026-07-26 09:20:00'),
(11, 7, 5, 5, 'Ваза впечатляет размером и качеством обжига, отличный акцент для гостиной.', 'pending', 0, NULL, NULL, '2026-07-27 11:10:00'),
(12, 8, 12, 2, 'Торшер шатается на треноге, ожидал более устойчивую конструкцию за такую цену.', 'rejected', 0, 2, '2026-07-20 15:00:00', '2026-07-19 17:25:00');
